R=lambda n:f'img/real/{n}.jpg'; C=lambda n:f'img/cut/{n}.png'; M=lambda n:f'img/render/{n}.jpg'
BLUE='#1D2FC4';CREAM='#FFFCEB';PALE='#EAF1FF';NAVY='#062B57';NEU='#F3F6FB'
def T(t,st):return f'<div class="t" style="{st}">{t}</div>'
def im(src,st,cut=False):return f'<img src="{src}" style="position:absolute;{st};{"object-fit:contain;filter:drop-shadow(0 6px 8px #0006)" if cut else "object-fit:cover;border-radius:3px;box-shadow:0 4px 10px #0005"}">'
def F(inner,bg,dark=True):return f'<div class="frame" style="background:{bg};color:{"#fff" if dark else "#0A2A5E"}">{inner}<div class="mk">devdha.in</div></div>'
glow='text-shadow:0 0 10px #fff9,0 0 30px #7FA6FF99;font-weight:700'
def W(t,top,size,col=''):return T(t,f'left:0;right:0;text-align:center;top:{top}px;font-size:{size}px;{glow};{col}')
dots=lambda n,on:'<div style="position:absolute;left:0;right:0;bottom:12px;display:flex;justify-content:center;gap:6px">'+''.join(f'<i style="width:7px;height:7px;border-radius:50%;background:{"#111" if i==on else "#1114"}"></i>' for i in range(n))+'</div>'
ban=lambda txt,l,t,w=240:f'<div style="position:absolute;left:{l}px;top:{t}px;width:{w}px;height:38px;background:#8a7f6bcc;color:#fff;font-weight:700;font-size:21px;padding:0 10px;line-height:38px;letter-spacing:1px;box-shadow:0 4px 10px #0004;white-space:nowrap;overflow:hidden">{txt}</div>'
chips=lambda items,l,t,w,col='#fff',bg='#ffffff22',fs=11:f'<div style="position:absolute;left:{l}px;top:{t}px;width:{w}px;display:flex;flex-wrap:wrap;gap:5px">'+''.join(f'<span style="background:{bg};color:{col};font-size:{fs}px;font-weight:600;padding:3px 8px;border-radius:10px">{x}</span>' for x in items)+'</div>'
def browser(inner,l,t,w,h):return f'<div style="position:absolute;left:{l}px;top:{t}px;width:{w}px;height:{h}px;background:#fff;border-radius:8px;box-shadow:0 8px 20px #0a2a5e66;overflow:hidden"><div style="height:22px;background:#0A2A5E;color:#fff;font-size:10px;padding:5px 9px">● ● ● &nbsp; yourshop.in</div>{inner}</div>'
def wall(c,r,hero=None):
    pool=[R('diwali'),R('minimen'),R('prachitam'),R('culturist'),R('posters'),R('clipa'),C('krishna'),R('desires'),R('atworkpost'),R('clipb'),C('honeycomb'),R('card'),R('clipc'),C('key'),C('mug'),M('polaroid'),M('calendar'),R('tee'),R('nexa'),R('atwork')]
    w=560/c;h=315/r;o=''
    for i in range(c*r):
        s=pool[(i*7+3)%len(pool)];o+=f'<div style="position:absolute;left:{(i%c)*w+1}px;top:{(i//c)*h+1}px;width:{w-2}px;height:{h-2}px;background:#16336f;overflow:hidden"><img src="{s}" style="width:100%;height:100%;object-fit:{"contain" if "cut" in s else "cover"}"></div>'
    return o
