def sc_page(s):
    fr=''.join(s['frames']);nf=len(s['frames'])
    rows=''.join(f'<tr><th>{a}</th><td>{b}</td></tr>' for a,b in s['beats'])
    prods=''.join(f'<tr><td>{a}</td><td>{b}</td><td>{status[c]}</td></tr>' for a,b,c in s['prod']) or '<tr><td colspan="3">none</td></tr>'
    tx=''.join(f'<div><span class="chip">{l}</span> {t}</div>' for l,t in zip(['EN','हिन्दी','मराठी'],s['txt']))
    cls='fr1' if nf==1 else ('fr2' if nf==2 else 'fr4')
    if len(s['prod'])>8: cls+=' tight'
    return page(f'S{s["id"]} · {s["n"]}',f'{s["t"]} · room: {s["room"]} · no prices',f'<div class="frs {cls}">{fr}</div><div class="cols"><div><table class="b">{rows}</table><div class="tr"><b>Transition:</b> {s["tr"]}</div></div><div><table class="b"><tr><th style="width:26%">Item</th><th>Source in Drive / project</th><th style="width:20%">Type</th></tr>{prods}</table><div class="l3" style="margin-top:4px">{tx}</div></div></div>')
def page(t,sub,body):return f'<div class="pg"><div class="top"><h2>{t}</h2><small>{sub}</small></div>{body}</div>'
def tbl(h,rows):return '<table class="wide"><tr>'+''.join(f'<th>{x}</th>' for x in h)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
